/**
 * Request - Rsc
 *
 * @module server/handlers/request/rsc
 */
import { BaseHandler } from "../../response/base.js";
import { isRSCEnabled } from "../../../../utils/index.js";
import { handleRSCEndpoint } from "../../../services/rsc/endpoints/index.js";
import { applySecurityHeadersWithNonce } from "../api/security-headers.js";
import { applyCORSHeaders } from "../../../../security/index.js";
import { HTTP_NOT_FOUND, PRIORITY_MEDIUM } from "../../../../utils/constants/index.js";
import { withSpan } from "../../../../observability/tracing/otlp-setup.js";
import { generateNonce } from "../../../../security/http/response/security-handler.js";
import { isExtendedFSAdapter } from "../../../../platform/adapters/fs/wrapper.js";
import { getHostEnv } from "../../../../platform/compat/process.js";
import { createHandlerDependencyPinningSource, getHandlerDependencyPinningIdentity, } from "../../utils/dependency-pinning-source.js";
import { isHostProjectCodeExecutionAllowed } from "../../../../security/project-locality.js";
export class RSCHandler extends BaseHandler {
    metadata = {
        name: "RSCHandler",
        priority: PRIORITY_MEDIUM,
        patterns: [{ pattern: "/_veryfront/rsc/", prefix: true }],
    };
    handle(req, ctx) {
        const { pathname } = new URL(req.url);
        if (!pathname.startsWith("/_veryfront/rsc/")) {
            return Promise.resolve(this.continue());
        }
        const endpoint = pathname.slice("/_veryfront/rsc/".length);
        return withSpan("rsc.handle", async () => {
            const isHydrationScript = endpoint === "client.js" || endpoint === "dom.js";
            const isClientModuleEndpoint = endpoint === "module";
            const isDeprecatedEndpoint = endpoint === "flight_page";
            if (!isRSCEnabled(ctx.config) &&
                !isHydrationScript &&
                !isClientModuleEndpoint &&
                !isDeprecatedEndpoint) {
                return this.respond(new Response("Not Found", { status: HTTP_NOT_FOUND }));
            }
            const nonce = generateNonce();
            const isLocalProject = ctx.isLocalProject === true;
            const dependencyPinningIdentity = getHandlerDependencyPinningIdentity(ctx);
            const dependencyPinningSource = createHandlerDependencyPinningSource(ctx);
            const execute = () => handleRSCEndpoint({
                req,
                pathname,
                projectDir: ctx.projectDir,
                ...dependencyPinningIdentity,
                dependencyPinningSource,
                adapter: ctx.adapter,
                config: ctx.config,
                isLocalProject,
                allowHostProjectCodeExecution: isHostProjectCodeExecutionAllowed(ctx),
                mode: isRSCProductionMode(ctx) ? "production" : "development",
                nonce,
                applicationIdentityHeaderNames: ctx.applicationIdentityHeaderNames,
                applicationIdentity: ctx.applicationIdentity ?? null,
            });
            const fsAdapter = ctx.adapter.fs;
            const isMultiProject = dependencyPinningIdentity.projectSlug &&
                isExtendedFSAdapter(fsAdapter) &&
                fsAdapter.isMultiProjectMode();
            const res = isMultiProject
                ? await fsAdapter.runWithContext(dependencyPinningIdentity.projectSlug, ctx.proxyToken || getHostEnv("VERYFRONT_API_TOKEN") || "", execute, dependencyPinningIdentity.projectId, {
                    productionMode: isRSCProductionMode(ctx),
                    releaseId: dependencyPinningIdentity.releaseId,
                    branch: dependencyPinningIdentity.branch ?? null,
                    environmentName: ctx.environmentName,
                })
                : await execute();
            if (!res) {
                return this.continue();
            }
            const headers = new Headers(res.headers);
            await applyCORSHeaders({
                request: req,
                headers,
                config: ctx.securityConfig?.cors,
            });
            applySecurityHeadersWithNonce(headers, ctx, nonce, req);
            return this.respond(new Response(res.body, {
                status: res.status,
                statusText: res.statusText,
                headers,
            }));
        }, { "rsc.pathname": pathname, "rsc.endpoint": endpoint });
    }
}
function isRSCProductionMode(ctx) {
    if (ctx.config?.fs?.veryfront?.productionMode === true)
        return true;
    return (ctx.resolvedEnvironment ?? ctx.requestContext?.mode) === "production";
}
